server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/nginx.crt;
    ssl_certificate_key /etc/nginx/ssl/nginx.key;

    # SSL configuration
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;

    # Main branch at root
    location / {
        root /var/www/main;
        index index.html;
        try_files $uri $uri/ =404;
    }

    # Dev branch at /dev/
    location /dev/ {
        alias /var/www/dev/;
        index index.html;
        try_files $uri $uri/ =404;
    }
}

